-file("src/data/month_gift_data.erl", 1).

-module(month_gift_data).

-export([ids/0,
         get/1,
         gifts/1,
         get_gift/1,
         get_pay_gift/1]).

-file("inc/common.hrl", 1).

-type p() :: bitstring().

-type z() :: non_neg_integer().

-type role_id() :: {pos_integer(), p(), z()}.

-type unit_id() :: {pos_integer(), pos_integer()}.

-type pos() :: {pos_integer(),
                non_neg_integer(),
                non_neg_integer()}.

-record(center,
        {ready = 0 :: 1 | 0,
         pid :: undefined | pid(),
         node :: undefined | atom(),
         center_platform = "" :: list(),
         center_zone_id = 0 :: non_neg_integer(),
         platform = <<>> :: bitstring(),
         zone_id = 0 :: non_neg_integer(),
         combine = [] :: [{bitstring(), non_neg_integer()}]}).

-record(notice_rec,
        {type = 11, digit_attr = [], str_attr = []}).

-file("src/data/month_gift_data.erl", 19).

-file("inc/month_gift.hrl", 1).

-record(m_month_gift, {lists = []}).

-record(month_gift_data,
        {id = 0,
         start_time,
         end_time,
         is_open = 0,
         desc1 = "",
         desc2 = "",
         title = "",
         item_list = []}).

-record(month_gift_item_data,
        {id = 0,
         gift_id = 0,
         group = 0,
         item_id = 0,
         bind = 0,
         num = 0,
         origin_price = [],
         price = [],
         min_lev = 0,
         max_lev = 0,
         sex = 0,
         classes = 0,
         min_lev_break = 0,
         max_lev_break = 0}).

-record(pay_gift_item_data,
        {gift_id = 0,
         item_id = 0,
         bind = 0,
         num = 0,
         type = 0,
         origin_price = [],
         price = [],
         min_lev = 0,
         max_lev = 0,
         sex = 0,
         classes = 0,
         min_lev_break = 0,
         max_lev_break = 0,
         desc = ""}).

-file("src/data/month_gift_data.erl", 20).

